import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.DU2spEDf.js";const u=JSON.parse('{"title":"Database & Security","description":"","frontmatter":{},"headers":[],"relativePath":"database-security.md","filePath":"database-security.md","lastUpdated":1787906606000}'),o={name:"database-security.md"};function i(c,t,s,n,l,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="database-security" tabindex="-1">Database &amp; Security <a class="header-anchor" href="#database-security" aria-label="Permalink to &quot;Database &amp; Security&quot;">​</a></h1><p>Ishuko uses <strong>PostgreSQL</strong> as its primary database, accessed from the backend via the <strong>SQLAlchemy</strong> ORM. The schema is organized around 6 main tables.</p><h2 id="user-table" tabindex="-1">User Table <a class="header-anchor" href="#user-table" aria-label="Permalink to &quot;User Table&quot;">​</a></h2><p>Describes system users; details are captured at signup.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>SQL Type</th><th>FastAPI Type</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>user_id</code></td><td>UUID</td><td>uuid</td><td>PRIMARY KEY</td><td>Unique identifier for the user</td></tr><tr><td><code>first_name</code></td><td>VARCHAR(255)</td><td>str</td><td>NOT NULL</td><td>First name</td></tr><tr><td><code>last_name</code></td><td>VARCHAR(255)</td><td>str</td><td>NOT NULL</td><td>Last name</td></tr><tr><td><code>email</code></td><td>VARCHAR(100)</td><td>str</td><td>NOT NULL</td><td>Email address</td></tr><tr><td><code>phone_number</code></td><td>VARCHAR(20)</td><td>str</td><td>UNIQUE, NOT NULL</td><td>Mobile money/SMS-linked number (Airtel, Zamtel, or MTN)</td></tr><tr><td><code>encrypted_pswrd</code></td><td>VARCHAR(255)</td><td>str</td><td>NOT NULL</td><td>Hashed password</td></tr><tr><td><code>status</code></td><td>ENUM</td><td>enum</td><td>NOT NULL</td><td><code>ACTIVE</code>, <code>DEACTIVATED</code>, <code>BANNED</code></td></tr><tr><td><code>role</code></td><td>ENUM</td><td>enum</td><td>NOT NULL</td><td><code>Buyer</code>, <code>Cooperative Manager</code>, <code>Admin</code></td></tr><tr><td><code>reset_pin</code></td><td>VARCHAR(6)</td><td>str</td><td>NULLABLE</td><td>Temporary 6-digit verification code</td></tr><tr><td><code>reset_pin_expires_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NULLABLE</td><td>Timezone-aware expiration for the reset code</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>DEFAULT CURRENT_TIMESTAMP</td><td>Account creation timestamp</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NOT NULL</td><td>Last update timestamp</td></tr></tbody></table><h2 id="cooperative-table" tabindex="-1">Cooperative Table <a class="header-anchor" href="#cooperative-table" aria-label="Permalink to &quot;Cooperative Table&quot;">​</a></h2><p>Captures cooperative registration data.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>SQL Type</th><th>FastAPI Type</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>coop_id</code></td><td>UUID</td><td>uuid</td><td>PRIMARY KEY</td><td>Unique identifier</td></tr><tr><td><code>cooperative_name</code></td><td>VARCHAR(255)</td><td>str</td><td>NOT NULL</td><td>Registered cooperative name</td></tr><tr><td><code>coop_leader_id</code></td><td>UUID</td><td>uuid</td><td>FOREIGN KEY → <code>user(user_id)</code></td><td>The leader&#39;s user account</td></tr><tr><td><code>longitude</code></td><td>Numeric(9,6)</td><td>float</td><td>NOT NULL</td><td>GPS longitude captured on device</td></tr><tr><td><code>latitude</code></td><td>Numeric(9,6)</td><td>float</td><td>NOT NULL</td><td>GPS latitude captured on device</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>DEFAULT CURRENT_TIMESTAMP</td><td>Record creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NOT NULL</td><td>Last update time</td></tr></tbody></table><h2 id="produce-listing-table" tabindex="-1">Produce Listing Table <a class="header-anchor" href="#produce-listing-table" aria-label="Permalink to &quot;Produce Listing Table&quot;">​</a></h2><p>Describes the produce a cooperative is selling — displayed on the marketplace. <code>price_per_kg</code> comes from the WFP HDX Zambia Food Prices dataset; <code>assigned_grade</code> comes from the AI quality checker.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>SQL Type</th><th>FastAPI Type</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>listing_id</code></td><td>UUID</td><td>uuid</td><td>PRIMARY KEY</td><td>Unique listing identifier</td></tr><tr><td><code>coop_id</code></td><td>UUID</td><td>uuid</td><td>FOREIGN KEY → <code>cooperative(coop_id)</code></td><td>Owning cooperative</td></tr><tr><td><code>crop_type</code></td><td>VARCHAR(10)</td><td>str</td><td>NOT NULL</td><td>Crop type being listed</td></tr><tr><td><code>quantity</code></td><td>DECIMAL(10,2)</td><td>float</td><td>NOT NULL</td><td>Batch volume</td></tr><tr><td><code>assigned_grade</code></td><td>VARCHAR(20)</td><td>str</td><td>NULLABLE</td><td>AI-assigned grade (A, B, C, D, REJECT)</td></tr><tr><td><code>price_per_kg</code></td><td>DECIMAL(10,2)</td><td>float</td><td>NULLABLE</td><td>Dynamic calculation from grade + live WFP price</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NOT NULL</td><td>Listing creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NOT NULL</td><td>Last update time</td></tr><tr><td><code>status</code></td><td>ENUM</td><td>enum</td><td>NOT NULL, DEFAULT <code>PENDING_GRADE</code></td><td><code>PENDING_GRADE</code>, <code>MARKETPLACE</code>, <code>REJECTED</code>, <code>RESERVED</code>, <code>COMPLETED</code></td></tr></tbody></table><h2 id="ai-grading-result-table" tabindex="-1">AI Grading Result Table <a class="header-anchor" href="#ai-grading-result-table" aria-label="Permalink to &quot;AI Grading Result Table&quot;">​</a></h2><p>Stores output from the AI quality checker needed for grade assignment.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>SQL Type</th><th>FastAPI Type</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>grade_id</code></td><td>UUID</td><td>uuid</td><td>PRIMARY KEY</td><td>Unique AI assessment identifier</td></tr><tr><td><code>listing_id</code></td><td>UUID</td><td>uuid</td><td>FOREIGN KEY → <code>produce_listing(listing_id)</code></td><td>The batch evaluated</td></tr><tr><td><code>insect_dmg_pct</code></td><td>DECIMAL(5,2)</td><td>float</td><td>NOT NULL</td><td>Insect/pest/weevil damage percentage</td></tr><tr><td><code>discoloured_pct</code></td><td>DECIMAL(5,2)</td><td>float</td><td>NOT NULL</td><td>Discoloration/moldy seed percentage</td></tr><tr><td><code>broken_pct</code></td><td>DECIMAL(5,2)</td><td>float</td><td>NOT NULL</td><td>Chipped/broken seed percentage</td></tr><tr><td><code>extraneous_pct</code></td><td>DECIMAL(5,2)</td><td>float</td><td>NOT NULL</td><td>Non-grain matter percentage (stones, cob fragments)</td></tr><tr><td><code>assessed_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NOT NULL</td><td>Time the AI inference completed</td></tr></tbody></table><h2 id="payment-table" tabindex="-1">Payment Table <a class="header-anchor" href="#payment-table" aria-label="Permalink to &quot;Payment Table&quot;">​</a></h2><p>Details of buyer payments after an order is placed; sourced from the Flutterwave webhook.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>SQL Type</th><th>FastAPI Type</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>payment_id</code></td><td>UUID</td><td>uuid</td><td>PRIMARY KEY</td><td>Unique transaction identifier</td></tr><tr><td><code>order_id</code></td><td>UUID</td><td>uuid</td><td>FOREIGN KEY → <code>order(order_id)</code></td><td>The related order</td></tr><tr><td><code>gross_amount</code></td><td>DECIMAL(10,2)</td><td>float</td><td>NOT NULL</td><td>Total amount paid by the wholesaler</td></tr><tr><td><code>platform_fee</code></td><td>DECIMAL(10,2)</td><td>float</td><td>NOT NULL</td><td>System fee (2% of gross amount)</td></tr><tr><td><code>net_disbursement</code></td><td>DECIMAL(10,2)</td><td>float</td><td>NOT NULL</td><td>Final payout to the cooperative (98%)</td></tr><tr><td><code>escrow_status</code></td><td>ENUM</td><td>enum</td><td>NOT NULL, DEFAULT <code>HELD</code></td><td><code>HELD</code>, <code>DISBURSED</code>, <code>REFUNDED</code></td></tr><tr><td><code>transaction_ref</code></td><td>VARCHAR(100)</td><td>str</td><td>NOT NULL</td><td>External webhook receipt token from telecom APIs</td></tr><tr><td><code>flutterwave_ref</code></td><td>VARCHAR(100)</td><td>str</td><td>NULLABLE</td><td>Flutterwave&#39;s internal receipt token</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>DEFAULT CURRENT_TIMESTAMP</td><td>Payment fulfillment time</td></tr></tbody></table><h2 id="order-table" tabindex="-1">Order Table <a class="header-anchor" href="#order-table" aria-label="Permalink to &quot;Order Table&quot;">​</a></h2><p>Individual orders placed by buyers; a token number is generated per order.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>SQL Type</th><th>FastAPI Type</th><th>Constraints</th><th>Description</th></tr></thead><tbody><tr><td><code>order_id</code></td><td>UUID</td><td>uuid</td><td>PRIMARY KEY</td><td>Unique order identifier</td></tr><tr><td><code>listing_id</code></td><td>UUID</td><td>uuid</td><td>FOREIGN KEY → <code>produce_listing(listing_id)</code></td><td>The AI-verified batch purchased</td></tr><tr><td><code>buyer_id</code></td><td>UUID</td><td>uuid</td><td>FOREIGN KEY → <code>user(buyer_id)</code></td><td>The purchasing wholesaler</td></tr><tr><td><code>pickup_date</code></td><td>DATE</td><td>date</td><td>NOT NULL</td><td>Buyer-selected pickup date</td></tr><tr><td><code>token_number</code></td><td>VARCHAR(6)</td><td>str</td><td>NOT NULL</td><td>Single-use code for the depot handshake</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NOT NULL</td><td>Order placement time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>datetime</td><td>NOT NULL</td><td>Last update time</td></tr><tr><td><code>order_status</code></td><td>ENUM</td><td>enum</td><td>NOT NULL</td><td><code>AWAITING_DEPOSIT</code>, <code>ESCROWED</code>, <code>COLLECTED</code>, <code>EXPIRED</code></td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><h3 id="password-security" tabindex="-1">Password Security <a class="header-anchor" href="#password-security" aria-label="Permalink to &quot;Password Security&quot;">​</a></h3><p>Passwords are never stored in plain text. Before being saved, they are hashed with <strong>bcrypt</strong> via the <strong>Passlib</strong> library — the application stores the hash, never the original password.</p><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>Protected endpoints require a valid <strong>JWT</strong>. After successful login, the backend issues a signed JWT, signed with <code>JWT_SECRET_KEY</code> using <strong>HS256</strong>, expiring according to <code>JWT_EXPIRE_DAYS</code>.</p><p>Requests to protected endpoints must include:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;access_token&gt;</span></span></code></pre></div><p>Missing, invalid, or expired tokens are rejected.</p><h3 id="role-based-access-control" tabindex="-1">Role-Based Access Control <a class="header-anchor" href="#role-based-access-control" aria-label="Permalink to &quot;Role-Based Access Control&quot;">​</a></h3><p>Access is controlled via <code>user_type</code>. Admin-only endpoints check:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user_type </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ADMIN&quot;</span></span></code></pre></div><p>This check is enforced through a dedicated authentication dependency in the backend. Other roles (e.g. Buyers) do not have access to admin-only endpoints.</p><h3 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h3><p>CORS controls which frontend applications may communicate with the API.</p><ul><li>Allowed origins are configured via the <code>CORS_ORIGINS</code> environment variable.</li><li>The application uses an <strong>explicit allow-list</strong> rather than a wildcard — important because the API allows credentials where required.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CORS_ORIGINS=https://example-frontend.com,https://www.example-frontend.com</span></span></code></pre></div><p>Use the actual production frontend URL in deployment configuration.</p><h3 id="environment-variables-secrets" tabindex="-1">Environment Variables &amp; Secrets <a class="header-anchor" href="#environment-variables-secrets" aria-label="Permalink to &quot;Environment Variables &amp; Secrets&quot;">​</a></h3><p>Sensitive configuration is stored as environment variables / platform config vars, never committed to source:</p><ul><li><code>JWT_SECRET_KEY</code></li><li>Database credentials</li><li>Other deployment-specific configuration</li></ul><p><code>.env</code> and any file containing secrets must never be committed to the repository.</p><h3 id="escrow-fraud-prevention" tabindex="-1">Escrow Fraud Prevention <a class="header-anchor" href="#escrow-fraud-prevention" aria-label="Permalink to &quot;Escrow Fraud Prevention&quot;">​</a></h3><p>Funds can never be released without a matching 6-digit OTP cryptographic hash.</p><h3 id="data-privacy" tabindex="-1">Data Privacy <a class="header-anchor" href="#data-privacy" aria-label="Permalink to &quot;Data Privacy&quot;">​</a></h3><p>Location data provided by the cooperative manager is encrypted.</p>',45)])])}const b=d(o,[["render",i]]);export{u as __pageData,b as default};
